  Lemma seg_T2 : forall regs mem (N PL cfg CP r : word) K,
    regs118 regs N PL cfg CP -> getr regs 21 = r ->
    stk_ok RSEGS mem sp 80 -> ro_none mem -> relro_none mem ->
    (forall regs',
        regs118 regs' N PL cfg CP -> getr regs' 21 = r -> getr regs' 1 = Z_to_bv 64 0x2be20 -> getr regs' 10 = N ->
        keep4 regs regs' ->
        realizes RSEGS (mkCfg (mkst regs' (Z_to_bv 64 0x6c344) mem (seg_rom RSEGS)) model) K) ->
